from typing import Literal
from uuid import UUID

from pydantic import BaseModel, EmailStr, Field, field_validator

from app.modules.auth.phone import normalize_phone

Exam = Literal["grade_5", "ol", "al", "other"]
Language = Literal["en", "si", "ta"]

# Generated by the browser once and kept in a cookie; identifies the device for the
# new-device check and the one-device rule.
DeviceId = Field(min_length=8, max_length=128)
Password = Field(min_length=8, max_length=128)


class _PhoneBody(BaseModel):
    phone: str = Field(max_length=32, examples=["0771234567"])

    @field_validator("phone")
    @classmethod
    def _normalize(cls, v: str) -> str:
        return normalize_phone(v)


class _EmailBody(BaseModel):
    email: EmailStr = Field(max_length=254)

    @field_validator("email")
    @classmethod
    def _lower(cls, v: str) -> str:
        return v.strip().lower()


class OtpRequest(_PhoneBody):
    pass


class OtpRequested(BaseModel):
    expires_in: int        # seconds until the code expires
    resend_after: int      # seconds before another code may be requested


class Register(_EmailBody):
    password: str = Password
    full_name: str = Field(min_length=1, max_length=120)
    device_id: str = DeviceId

    @field_validator("full_name")
    @classmethod
    def _strip(cls, v: str) -> str:
        v = " ".join(v.split())
        if not v:
            raise ValueError("Enter your name.")
        return v


class Login(_EmailBody):
    password: str = Field(min_length=1, max_length=128)
    device_id: str = DeviceId


class GoogleLogin(BaseModel):
    id_token: str = Field(min_length=20, max_length=4096)
    device_id: str = DeviceId


class TokenPair(BaseModel):
    access_token: str
    refresh_token: str
    token_type: str = "bearer"
    expires_in: int        # access token lifetime, seconds


class DeviceCheck(BaseModel):
    """Sign-in from an unknown device: an SMS code went to the account's verified phone."""

    challenge: str
    phone_hint: str        # e.g. "•••• 4567"
    expires_in: int
    resend_after: int


class LoginResult(BaseModel):
    """Exactly one of `tokens` (signed in) or `device_check` (enter the SMS code first)."""

    status: Literal["signed_in", "device_check"]
    tokens: TokenPair | None = None
    device_check: DeviceCheck | None = None


class DeviceVerify(BaseModel):
    challenge: str = Field(min_length=20, max_length=2048)
    code: str = Field(pattern=r"^\d{6}$")
    device_id: str = DeviceId


class DeviceResend(BaseModel):
    challenge: str = Field(min_length=20, max_length=2048)


class RefreshRequest(BaseModel):
    refresh_token: str = Field(min_length=20, max_length=200)


class PhoneVerify(_PhoneBody):
    code: str = Field(pattern=r"^\d{6}$")
    device_id: str = DeviceId


class EmailVerify(BaseModel):
    token: str = Field(min_length=20, max_length=200)


class RecoveryRequest(_EmailBody):
    pass


class RecoveryStart(BaseModel):
    token: str = Field(min_length=20, max_length=200)


class RecoveryStarted(BaseModel):
    needs_code: bool               # an SMS code went to the verified phone
    phone_hint: str | None = None
    resend_after: int | None = None


class RecoveryComplete(BaseModel):
    token: str = Field(min_length=20, max_length=200)
    code: str | None = Field(default=None, pattern=r"^\d{6}$")
    password: str = Password
    device_id: str = DeviceId


class ProfileUpdate(BaseModel):
    """PATCH: only fields sent are applied."""

    model_config = {"extra": "forbid"}

    full_name: str | None = Field(default=None, min_length=1, max_length=120)
    preferred_language: Language | None = None
    exam: Exam | None = None
    exam_year: int | None = Field(default=None, ge=2000, le=2100)
    school: str | None = Field(default=None, max_length=120)


class Workspace(BaseModel):
    """A tenant where the user is staff (owner, admin or teacher): a console they can open."""

    slug: str
    name: str
    role: str
    status: str                  # 'active', or 'pending' while EduZone reviews the application (draft mode)


class Me(BaseModel):
    user_id: UUID
    full_name: str
    email: str | None
    email_verified: bool
    phone: str | None
    phone_verified: bool
    has_password: bool
    preferred_language: str
    exam: str | None
    exam_year: int | None
    school: str | None
    # Membership in the tenant of this request (pre-migration: the tenant host). None when the
    # user hasn't joined or paid for anything here yet.
    member_id: UUID | None
    role: str | None
    workspaces: list[Workspace]
    cart_count: int = 0          # items in the signed-in user's cart (header badge)
